    tr, tc = points[2]
    dr = (tr > r) - (tr < r)
    dc = (tc > c) - (tc < c)
    nr, nc = abs(tr-r), abs(tc-c)
    # Approach the other marker diagonally, leaving its final diagonal step
    # for the end of the path; bridge any remaining distance in a straight line.
    diagonal_steps = max(0, min(nr, nc) - 1) if nr and nc else 0
    for _ in range(diagonal_steps):
